#!/usr/bin/env bash
# C-8y2 negative controls for the kernel-parametric capstone, on the collatz instance.
# Each mutant is compiled in a private overlay (lean --root on a temp copy; Formal/ and
# .lake/build are not touched) and MUST fail to check:
#   N1 graph:   the collatz MLIR with constant4 (the `1` of 3n+1, of n>>1 and of steps+1) set to 2,
#               network regenerated by capnet.py kdata; the committed token graph and proofs kept.
#               -> KP.ops_ok (decide over the generic OpChk) must fail.
#   N2 C ref:   the instance's C reference off by one (spec n fuel := C result + 1).
#               -> KP.good_run must fail.
#   N3 walk:    one walk-certificate row mutated (rho of the first `recs` entry 0 -> 1).
#               -> KP.recs_chk / init_chk must fail.
#   N0 (sanity) the unmutated overlay must check (so a failure above is the mutation's).
# usage: formal/lean/Wip/C8y2/negctl.sh      (needs Wip/C8y2/obj built by lc.sh, or the
#        KernelCap* modules in .lake/build)
set -uo pipefail
L=/home/user/asyncfpga3/formal/lean
R=/home/user/asyncfpga3
W=$L/Wip/C8y2
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
src() { # the committed (or WIP) source of a module
  if [ -f "$L/Formal/Net/$1.lean" ]; then echo "$L/Formal/Net/$1.lean"; else echo "$W/src/Formal/Net/$1.lean"; fi; }
compile() { # $1 = overlay dir; compiles CollatzCapData then KernelCapCollatz; rc 0 iff both check
  local O=$1
  mkdir -p "$O/obj"
  cp -rsn "$L/.lake/build/lib/lean/Formal" "$O/obj/" 2>/dev/null
  [ -d "$W/obj/Formal" ] && cp -rsn "$W/obj/Formal" "$O/obj/" 2>/dev/null
  for m in CollatzCapData KernelCapCollatz; do
    rm -f "$O/obj/Formal/Net/$m.olean" "$O/obj/Formal/Net/$m.ilean"
    (cd "$R/formal" && ./slot.sh lake env bash -c "LEAN_PATH=$O/obj:\$LEAN_PATH lean -DautoImplicit=false --root=$O/src -o $O/obj/Formal/Net/$m.olean $O/src/Formal/Net/$m.lean") \
      > "$O/$m.log" 2>&1
    if grep -q "error" "$O/$m.log"; then echo "  $m: $(grep -m1 -o 'error.*' "$O/$m.log" | cut -c1-150)"; return 1; fi
  done
  return 0
}
mk() { mkdir -p "$T/$1/src/Formal/Net"; cp "$(src CollatzCapData)" "$(src KernelCapCollatz)" "$T/$1/src/Formal/Net/"; }
fail=0
# N0 sanity
mk n0
if compile "$T/n0"; then echo "[negctl] N0 unmutated overlay checks (sanity)"; else echo "[negctl] N0 FAILED: overlay broken"; fail=1; fi
# N1 graph mutation through the real front end
mk n1
mkdir -p "$T/mlir/build/frontend/collatz/comp"
sed 's/handshake.name = "constant4", value = 1 : i32/handshake.name = "constant4", value = 2 : i32/' \
  "$R/cloud/fixtures/frontend/collatz/comp/handshake_transformed.mlir" > "$T/n1.mlir"
cmp -s "$T/n1.mlir" "$R/cloud/fixtures/frontend/collatz/comp/handshake_transformed.mlir" && { echo "[negctl] N1 sed did not apply"; fail=1; }
CAPNET_MLIR_collatz="$T/n1.mlir" python3 "$R/formal/tools/capnet/capnet.py" --kernel collatz kdata \
  -o "$T/n1/src/Formal/Net/CollatzCapData.lean" 2>/dev/null || { echo "[negctl] N1 capnet failed"; fail=1; }
cmp -s "$T/n1/src/Formal/Net/CollatzCapData.lean" "$(src CollatzCapData)" && { echo "[negctl] N1 network unchanged?"; fail=1; }
if compile "$T/n1"; then echo "[negctl] N1 graph mutant CHECKED -- control failed"; fail=1; else echo "[negctl] N1 graph mutant rejected"; fi
# N2 wrong C reference
mk n2
sed -i 's/  spec n fuel := (CollatzHw.collatzC fuel n).getD 0$/  spec n fuel := (CollatzHw.collatzC fuel n).getD 0 + 1/' "$T/n2/src/Formal/Net/KernelCapCollatz.lean"
grep -q "getD 0 + 1" "$T/n2/src/Formal/Net/KernelCapCollatz.lean" || { echo "[negctl] N2 sed did not apply"; fail=1; }
if compile "$T/n2"; then echo "[negctl] N2 C-reference mutant CHECKED -- control failed"; fail=1; else echo "[negctl] N2 wrong C reference rejected"; fi
# N3 walk certificate
mk n3
sed -i 's/^def recs : List (Nat × Nat × Nat × Bool × List Nat) := \[(\([0-9]*\), \([0-9]*\), 0,/def recs : List (Nat × Nat × Nat × Bool × List Nat) := [(\1, \2, 1,/' "$T/n3/src/Formal/Net/CollatzCapData.lean"
cmp -s "$T/n3/src/Formal/Net/CollatzCapData.lean" "$(src CollatzCapData)" && { echo "[negctl] N3 sed did not apply"; fail=1; }
if compile "$T/n3"; then echo "[negctl] N3 walk mutant CHECKED -- control failed"; fail=1; else echo "[negctl] N3 walk-certificate mutant rejected"; fi
[ $fail -eq 0 ] && echo "[negctl] PASS" || echo "[negctl] FAIL"
exit $fail
